<?php
require_once __DIR__.'/_bootstrap.php'; requireMethod('POST'); $b=requestBody(); $action=strtolower(trim((string)($b['action']??'login'))); $username=trim((string)($b['username']??'')); $password=(string)($b['password']??'');
if (!in_array($action,['login','register'],true)) jsonResponse(400,['ok'=>false,'error'=>'Invalid action.']);
if (!preg_match('/^[A-Za-z0-9_]{3,24}$/',$username)) jsonResponse(400,['ok'=>false,'error'=>'Username must be 3–24 characters using letters, numbers, or underscores.']);
if (strlen($password)<8 || strlen($password)>72) jsonResponse(400,['ok'=>false,'error'=>'Password must be 8–72 bytes long.']);
try { $pdo=db(); if ($action==='register') { $st=$pdo->prepare('INSERT INTO public.users (username,password_hash) VALUES (:u,:h) RETURNING id,username'); try { $st->execute(['u'=>$username,'h'=>password_hash($password,PASSWORD_BCRYPT,['cost'=>12])]); $u=$st->fetch(); } catch(PDOException $e) { if ($e->getCode()==='23505') jsonResponse(409,['ok'=>false,'error'=>'That username is already taken.']); throw $e; } } else { $st=$pdo->prepare('SELECT id,username,password_hash FROM public.users WHERE lower(username)=lower(:u) LIMIT 1'); $st->execute(['u'=>$username]); $r=$st->fetch(); if (!$r || !password_verify($password,$r['password_hash'])) jsonResponse(401,['ok'=>false,'error'=>'Incorrect username or password.']); $pdo->prepare('UPDATE public.users SET last_login_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['id'=>$r['id']]); $u=['id'=>$r['id'],'username'=>$r['username']]; } setSession($u); jsonResponse(200,['ok'=>true,'user'=>['id'=>(string)$u['id'],'username'=>$u['username']]]); }
catch(Throwable $e) { error_log('[Bastion auth] '.$e->getMessage()); jsonResponse(500,['ok'=>false,'error'=>'Authentication failed due to a server error.']); }
